"use client";

import { useEffect, useState } from "react";

type Metrics = {
  cpu: number;
  mem: number;
  ssd: number;
  temp: number;
};

const drift = (v: number, range: number, min = 0, max = 100) => {
  const next = v + (Math.random() - 0.5) * range;
  return Math.max(min, Math.min(max, next));
};

const initial: Record<"node-01" | "node-02", Metrics> = {
  "node-01": { cpu: 14, mem: 41, ssd: 23, temp: 48 },
  "node-02": { cpu: 9, mem: 38, ssd: 19, temp: 45 },
};

const useFakeMetrics = () => {
  const [data, setData] = useState(initial);

  useEffect(() => {
    const id = setInterval(() => {
      setData((d) => ({
        "node-01": {
          cpu: drift(d["node-01"].cpu, 6, 2, 90),
          mem: drift(d["node-01"].mem, 2, 20, 80),
          ssd: d["node-01"].ssd,
          temp: drift(d["node-01"].temp, 1.5, 40, 65),
        },
        "node-02": {
          cpu: drift(d["node-02"].cpu, 6, 2, 90),
          mem: drift(d["node-02"].mem, 2, 20, 80),
          ssd: d["node-02"].ssd,
          temp: drift(d["node-02"].temp, 1.5, 40, 65),
        },
      }));
    }, 1500);
    return () => clearInterval(id);
  }, []);

  return data;
};

const Bar = ({ value, suffix = "%" }: { value: number; suffix?: string }) => {
  const blocks = 12;
  const filled = Math.round((value / 100) * blocks);
  return (
    <span className="text-muted-foreground tabular-nums">
      <span className="text-foreground">
        {"▮".repeat(filled)}
      </span>
      {"▯".repeat(blocks - filled)}{" "}
      <span className="text-foreground">
        {value.toFixed(0).padStart(2, " ")}
        {suffix}
      </span>
    </span>
  );
};

const PiBoard = () => (
  <svg
    viewBox="0 0 200 140"
    className="w-full h-auto"
    fill="none"
    stroke="currentColor"
    strokeWidth="1"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    {/* PCB outline */}
    <rect x="4" y="4" width="192" height="132" rx="4" />
    {/* mounting holes */}
    <circle cx="12" cy="12" r="2" />
    <circle cx="188" cy="12" r="2" />
    <circle cx="12" cy="128" r="2" />
    <circle cx="188" cy="128" r="2" />
    {/* GPIO header */}
    <rect x="20" y="10" width="120" height="6" />
    {Array.from({ length: 20 }).map((_, i) => (
      <line
        key={i}
        x1={22 + i * 6}
        y1={10}
        x2={22 + i * 6}
        y2={16}
      />
    ))}
    {/* SoC */}
    <rect x="60" y="50" width="44" height="44" rx="2" />
    <text
      x="82"
      y="76"
      fontSize="6"
      textAnchor="middle"
      stroke="none"
      fill="currentColor"
      className="font-mono"
    >
      BCM2712
    </text>
    {/* RAM */}
    <rect x="118" y="56" width="22" height="14" rx="1" />
    {/* USB ports */}
    <rect x="150" y="36" width="22" height="18" />
    <rect x="150" y="60" width="22" height="18" />
    {/* Ethernet */}
    <rect x="150" y="90" width="26" height="20" />
    {/* HDMI / power */}
    <rect x="22" y="62" width="14" height="10" />
    <rect x="22" y="80" width="14" height="10" />
    <rect x="22" y="98" width="10" height="8" />
    {/* microSD hint on underside */}
    <line x1="14" y1="118" x2="40" y2="118" strokeDasharray="2 2" />
  </svg>
);

const NodeReadout = ({
  name,
  m,
}: {
  name: string;
  m: Metrics;
}) => (
  <div className="flex flex-col gap-1 text-xs">
    <div className="flex items-center gap-2 text-foreground">
      <span className="inline-block size-1.5 rounded-full bg-foreground animate-pulse" />
      <span>{name}</span>
      <span className="text-muted-foreground">· ready</span>
    </div>
    <div className="grid grid-cols-[2.5rem_1fr] gap-x-3 gap-y-0.5 pl-3.5">
      <span className="text-muted-foreground">cpu</span>
      <Bar value={m.cpu} />
      <span className="text-muted-foreground">mem</span>
      <Bar value={m.mem} />
      <span className="text-muted-foreground">ssd</span>
      <Bar value={m.ssd} />
      <span className="text-muted-foreground">temp</span>
      <span className="tabular-nums text-foreground">
        {m.temp.toFixed(0)}°C
      </span>
    </div>
  </div>
);

export const PiCluster = () => {
  const m = useFakeMetrics();

  return (
    <div className="flex flex-col gap-4 w-full max-w-sm">
      <div className="text-muted-foreground/80">
        <PiBoard />
      </div>
      <div className="flex flex-col gap-3">
        <NodeReadout name="node-01" m={m["node-01"]} />
        <NodeReadout name="node-02" m={m["node-02"]} />
      </div>
      <p className="text-xs text-muted-foreground">
        hosted on a 2-node k3s cluster · raspberry pi 5
      </p>
    </div>
  );
};
